import{_ as a,o as t,c as d,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/notifications.md","filePath":"dev/domain/notifications.md"}'),o={name:"dev/domain/notifications.md"};function i(c,e,s,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[n(`<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><h2 id="in-app-and-push" tabindex="-1">In-app and push <a class="header-anchor" href="#in-app-and-push" aria-label="Permalink to &quot;In-app and push&quot;">​</a></h2><p>Every notification extends <code>AppNotification</code> (type, <code>translationKey</code>, data) and is sent through <code>NotificationServiceContract</code>, <strong>queued</strong> to the <code>database</code> channel and <code>LocalizedFcmChannel</code>.</p><ul><li>The <strong>inbox stores every locale</strong>; push renders per device locale.</li><li>Platform-event notifications go to <code>SystemUser::notifiableAdmins()</code>.</li><li>Every new lang file needs both <code>en</code> and <code>ar</code> entries.</li></ul><p>Each actor reads its inbox at <code>…/notifications</code> (list, <code>unread-count</code>, <code>mark-as-read</code>, <code>mark-all-as-read</code>) under <code>clients</code>, <code>centers</code> and <code>admin</code>.</p><h2 id="campaigns" tabindex="-1">Campaigns <a class="header-anchor" href="#campaigns" aria-label="Permalink to &quot;Campaigns&quot;">​</a></h2><p>Admin-only (<code>notification_campaigns.manage</code>). A campaign targets <strong>Clients</strong> or <strong>Centers</strong> (a Centers audience reaches <code>Center::notifiableUsers()</code>) over the <strong>push</strong> or <strong>whatsapp</strong> channel.</p><h3 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft ─► scheduled ─► sending ─► sent</span></span>
<span class="line"><span>  │          │            └────► failed</span></span>
<span class="line"><span>  └──────────┴──► cancelled (terminal)</span></span></code></pre></div><ul><li>Edit content and targets only while <code>draft</code> or <code>scheduled</code>.</li><li>A <code>sending</code> campaign cannot be deleted.</li><li>Start only through <code>CampaignService::sendNow()</code> (a conditional update); only <code>markFinished</code> ends <code>sending</code>.</li><li><code>notifications:dispatch-due-campaigns</code> runs every minute and sends scheduled campaigns that are due.</li></ul><h3 id="targeting-and-delivery" tabindex="-1">Targeting and delivery <a class="header-anchor" href="#targeting-and-delivery" aria-label="Permalink to &quot;Targeting and delivery&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td>Target mode <code>all</code></td><td>No target rows</td></tr><tr><td>Target mode <code>selected</code></td><td>1–5000 existing ids of the audience model</td></tr><tr><td>Push</td><td>Needs both <code>en</code> and <code>ar</code> title and body</td></tr><tr><td>WhatsApp</td><td>Template parameters must equal the template&#39;s variable count</td></tr><tr><td>Retries</td><td>WhatsApp writes one delivery row per recipient and skips existing ones, so retries never resend</td></tr></tbody></table><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p><code>admin/notification-campaigns</code> (CRUD, <code>schedule</code>, <code>send</code>, <code>cancel</code>, <code>duplicate</code>, <code>deliveries</code>) and <code>admin/whatsapp-templates</code> (CRUD, <code>whatsapp_templates.manage</code>).</p>`,14)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
